//! The orthogonal polynomials and Legendre functions against mpmath (ground
//! truth) and SciPy (parity), for `f64` and `xprec::Df64`, plus SciPy's
//! non-finite and zero results.
//!
//! Reference data: `tests/data`, generated by `scripts/gen_specials_reference.py`
//! (`orthogonal`). The last argument of an integer-degree row is its *scale*,
//! the largest `|p_j|` of the recurrence for `j <= n`. A polynomial value near
//! a zero has an absolute rather than a relative error of about `C (n + 1) eps
//! scale`, so each assertion has a relative tolerance and that absolute floor;
//! the constants `C` below are 3x or more above the worst measured error.
//!
//! The `f64` rows run in every configuration; the `Df64` tests need the `xprec`
//! feature (on by default).

#[path = "../src/refdata.rs"]
mod refdata;

use refdata::{error, orthogonal_special_values, rows, same, Row};
use specials::{LegendreType, Real};
#[cfg(feature = "xprec")]
use xprec::Df64;

/// Names of the integer-degree rows: the last argument is the scale.
const INT_NAMES: [&str; 15] = [
    "eval_jacobi_int",
    "eval_sh_jacobi_int",
    "eval_gegenbauer_int",
    "eval_chebyt_int",
    "eval_chebyu_int",
    "eval_chebyc_int",
    "eval_chebys_int",
    "eval_sh_chebyt_int",
    "eval_sh_chebyu_int",
    "eval_legendre_int",
    "eval_sh_legendre_int",
    "eval_laguerre_int",
    "eval_genlaguerre_int",
    "eval_hermite",
    "eval_hermitenorm",
];

/// Names of the real-degree rows (no scale): f64 values; `Df64` evaluates the
/// f64 kernel for a non-integer degree.
const REAL_NAMES: [&str; 13] = [
    "eval_jacobi",
    "eval_sh_jacobi",
    "eval_gegenbauer",
    "eval_chebyt",
    "eval_chebyu",
    "eval_chebyc",
    "eval_chebys",
    "eval_sh_chebyt",
    "eval_sh_chebyu",
    "eval_legendre",
    "eval_sh_legendre",
    "eval_laguerre",
    "eval_genlaguerre",
];

/// Rows of the Legendre functions of integer degree and order: the last
/// argument is the scale.
const LEGENDRE_NAMES: [&str; 6] = [
    "assoc_legendre_p",
    "assoc_legendre_p_t3",
    "assoc_legendre_p_norm",
    "assoc_legendre_p_norm_t3",
    "sph_legendre_p",
    "pmv_int",
];

fn eval<T: Real>(name: &str, a: &[T]) -> T {
    let i = |k: usize| a[k].approx_f64() as i64;
    let i32_ = |k: usize| a[k].approx_f64() as i32;
    match name {
        "eval_jacobi_int" => specials::eval_jacobi_int(i(0), a[1], a[2], a[3]),
        "eval_sh_jacobi_int" => specials::eval_sh_jacobi_int(i(0), a[1], a[2], a[3]),
        "eval_gegenbauer_int" => specials::eval_gegenbauer_int(i(0), a[1], a[2]),
        "eval_chebyt_int" => specials::eval_chebyt_int(i(0), a[1]),
        "eval_chebyu_int" => specials::eval_chebyu_int(i(0), a[1]),
        "eval_chebyc_int" => specials::eval_chebyc_int(i(0), a[1]),
        "eval_chebys_int" => specials::eval_chebys_int(i(0), a[1]),
        "eval_sh_chebyt_int" => specials::eval_sh_chebyt_int(i(0), a[1]),
        "eval_sh_chebyu_int" => specials::eval_sh_chebyu_int(i(0), a[1]),
        "eval_legendre_int" => specials::eval_legendre_int(i(0), a[1]),
        "eval_sh_legendre_int" => specials::eval_sh_legendre_int(i(0), a[1]),
        "eval_laguerre_int" => specials::eval_laguerre_int(i(0), a[1]),
        "eval_genlaguerre_int" => specials::eval_genlaguerre_int(i(0), a[1], a[2]),
        "eval_hermite" => specials::eval_hermite(i(0), a[1]),
        "eval_hermitenorm" => specials::eval_hermitenorm(i(0), a[1]),
        "eval_jacobi" => specials::eval_jacobi(a[0], a[1], a[2], a[3]),
        "eval_sh_jacobi" => specials::eval_sh_jacobi(a[0], a[1], a[2], a[3]),
        "eval_gegenbauer" => specials::eval_gegenbauer(a[0], a[1], a[2]),
        "eval_chebyt" => specials::eval_chebyt(a[0], a[1]),
        "eval_chebyu" => specials::eval_chebyu(a[0], a[1]),
        "eval_chebyc" => specials::eval_chebyc(a[0], a[1]),
        "eval_chebys" => specials::eval_chebys(a[0], a[1]),
        "eval_sh_chebyt" => specials::eval_sh_chebyt(a[0], a[1]),
        "eval_sh_chebyu" => specials::eval_sh_chebyu(a[0], a[1]),
        "eval_legendre" => specials::eval_legendre(a[0], a[1]),
        "eval_sh_legendre" => specials::eval_sh_legendre(a[0], a[1]),
        "eval_laguerre" => specials::eval_laguerre(a[0], a[1]),
        "eval_genlaguerre" => specials::eval_genlaguerre(a[0], a[1], a[2]),
        "pmv" => specials::pmv(a[0], a[1], a[2]),
        "pmv_int" => specials::pmv(a[0], a[1], a[2]),
        "legendre_p" => specials::legendre_p(i32_(0), a[1]),
        "assoc_legendre_p" => {
            specials::assoc_legendre_p(i32_(0), i32_(1), a[2], LegendreType::Ferrers)
        }
        "assoc_legendre_p_t3" => {
            specials::assoc_legendre_p(i32_(0), i32_(1), a[2], LegendreType::Outside)
        }
        "assoc_legendre_p_norm" => {
            specials::assoc_legendre_p_norm(i32_(0), i32_(1), a[2], LegendreType::Ferrers)
        }
        "assoc_legendre_p_norm_t3" => {
            specials::assoc_legendre_p_norm(i32_(0), i32_(1), a[2], LegendreType::Outside)
        }
        "sph_legendre_p" => specials::sph_legendre_p(i32_(0), i32_(1), a[2]),
        "lqn" => specials::lqn(i(0) as usize, a[1]).0[i(0) as usize],
        "lqn_d" => specials::lqn(i(0) as usize, a[1]).1[i(0) as usize],
        "lqmn" => {
            let (m, n) = (i(0) as usize, i(1) as usize);
            specials::lqmn(m, n, a[2]).0[m * (n + 1) + n]
        }
        "lqmn_d" => {
            let (m, n) = (i(0) as usize, i(1) as usize);
            specials::lqmn(m, n, a[2]).1[m * (n + 1) + n]
        }
        _ => unreachable!("{name}"),
    }
}

/// The degree of a row of an integer-degree or Legendre file (its first
/// argument; the order `m` is the second argument of the Legendre files).
fn degree(r: &Row) -> f64 {
    r.args[0].0.abs()
}

/// The absolute floor of a polynomial row: `c (n + 1) eps scale` as the
/// `floor` argument of `error`, for the relative tolerance `tol`.
fn floor_of(r: &Row, c: f64, eps: f64, tol: f64) -> f64 {
    let scale = r.args.last().expect("scale").0;
    c * (degree(r) + 1.0) * eps * scale / tol
}

/// Tolerances `(name, f64 vs mpmath, f64 vs SciPy, Df64 vs mpmath, c f64, c Df64)`.
///
/// The relative tolerances apply away from the zeros; the constants `c` give
/// the absolute floor `c (n + 1) eps scale` near them.
const INT_TOL: [(&str, f64, f64, f64, f64, f64); 15] = [
    ("eval_jacobi_int", 1e-11, 1e-11, 1e-28, 100.0, 100.0),
    ("eval_sh_jacobi_int", 1e-11, 1e-11, 1e-28, 100.0, 100.0),
    ("eval_gegenbauer_int", 1e-11, 1e-11, 1e-28, 100.0, 100.0),
    ("eval_chebyt_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_chebyu_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_chebyc_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_chebys_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_sh_chebyt_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_sh_chebyu_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_legendre_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_sh_legendre_int", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_laguerre_int", 1e-11, 1e-11, 1e-28, 100.0, 100.0),
    ("eval_genlaguerre_int", 1e-11, 1e-11, 1e-28, 100.0, 100.0),
    ("eval_hermite", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
    ("eval_hermitenorm", 1e-12, 1e-12, 1e-29, 100.0, 100.0),
];

#[test]
fn integer_degree_f64_matches_mpmath_and_scipy() {
    for (name, tol_mp, tol_sp, _, c, _) in INT_TOL {
        let all = rows(name);
        assert!(all.len() > 100, "{name}: {} rows", all.len());
        for r in all.iter().filter(|r| r.is_f64()) {
            let a: Vec<f64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, floor_of(r, c, f64::EPSILON, tol_mp));
            assert!(
                e <= tol_mp,
                "{name}{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
                r.line,
                r.reference
            );
            if let Some(s) = r.scipy.filter(|s| s.is_finite()) {
                if r.reference.0.is_finite() {
                    let e = error(got, (s, 0.0), floor_of(r, c, f64::EPSILON, tol_sp));
                    assert!(
                        e <= tol_sp,
                        "{name}{a:?} (line {}): got {got:e}, scipy {s:e}, err {e:e}",
                        r.line
                    );
                }
            }
        }
    }
}

#[cfg(feature = "xprec")]
#[test]
fn integer_degree_df64_matches_mpmath() {
    for (name, _, _, tol, _, c) in INT_TOL {
        for r in rows(name) {
            let a: Vec<Df64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, floor_of(&r, c, 2.0_f64.powi(-105), tol));
            assert!(
                e <= tol,
                "{name}{:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
                r.args,
                r.line,
                r.reference
            );
        }
    }
}

/// Tolerances of the real-degree rows `(name, f64 vs mpmath, f64 vs SciPy)`: the
/// Cephes hypergeometric series loses a few digits for large degrees (its own
/// header gives a peak relative error of 1.2e-11).
const REAL_TOL: [(&str, f64, f64); 13] = [
    ("eval_jacobi", 1e-9, 1e-12),
    ("eval_sh_jacobi", 1e-9, 1e-12),
    ("eval_gegenbauer", 1e-9, 1e-12),
    ("eval_chebyt", 1e-9, 1e-12),
    ("eval_chebyu", 1e-9, 1e-12),
    ("eval_chebyc", 1e-9, 1e-12),
    ("eval_chebys", 1e-9, 1e-12),
    ("eval_sh_chebyt", 1e-9, 1e-12),
    ("eval_sh_chebyu", 1e-9, 1e-12),
    ("eval_legendre", 1e-9, 1e-12),
    ("eval_sh_legendre", 1e-9, 1e-12),
    ("eval_laguerre", 1e-9, 1e-12),
    ("eval_genlaguerre", 1e-9, 1e-12),
];

/// The absolute floor of a real-degree row: the series are summed with
/// cancellation near the zeros of the function, where the error is absolute.
fn real_floor(name: &str, a: &[f64], tol: f64) -> f64 {
    let _ = name;
    let n = a[0].abs();
    1e-13 * (n + 1.0) / tol
}

#[test]
fn real_degree_f64_matches_mpmath_and_scipy() {
    for (name, tol_mp, tol_sp) in REAL_TOL {
        let all = rows(name);
        assert!(all.len() > 30, "{name}: {} rows", all.len());
        for r in all.iter().filter(|r| r.is_f64()) {
            let a: Vec<f64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, real_floor(name, &a, tol_mp));
            assert!(
                e <= tol_mp,
                "{name}{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
                r.line,
                r.reference
            );
            if let Some(s) = r.scipy.filter(|s| s.is_finite()) {
                let e = error(got, (s, 0.0), real_floor(name, &a, tol_sp));
                assert!(
                    e <= tol_sp,
                    "{name}{a:?} (line {}): got {got:e}, scipy {s:e}, err {e:e}",
                    r.line
                );
            }
        }
    }
}

/// `Df64` evaluates the f64 kernel for a non-integer degree, so its accuracy
/// there is that of `f64`.
#[cfg(feature = "xprec")]
#[test]
fn real_degree_df64_is_as_accurate_as_the_f64_kernel() {
    for (name, tol_mp, _) in REAL_TOL {
        for r in rows(name).iter().filter(|r| r.is_f64()) {
            let a: Vec<Df64> = r.args_as();
            let got = eval(name, &a);
            let af: Vec<f64> = r.args_as();
            let e = error(got, r.reference, real_floor(name, &af, tol_mp));
            assert!(
                e <= tol_mp,
                "{name}{af:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
                r.line,
                r.reference
            );
        }
    }
}

/// Tolerances of the Legendre rows `(name, f64 vs mpmath, f64 vs SciPy, Df64 vs
/// mpmath, c f64, c Df64)`. `pmv_int` is the integer-degree `pmv` (the xsref
/// table of `pmv` is checked in `xsref.rs`).
const LEGENDRE_TOL: [(&str, f64, f64, f64, f64, f64); 6] = [
    ("assoc_legendre_p", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
    ("assoc_legendre_p_t3", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
    ("assoc_legendre_p_norm", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
    ("assoc_legendre_p_norm_t3", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
    ("sph_legendre_p", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
    ("pmv_int", 1e-9, 1e-9, 1e-28, 100.0, 100.0),
];

/// The degree that sets the floor of a Legendre row: `n`, and `|m|` for the
/// order of the same size.
fn legendre_floor(r: &Row, c: f64, eps: f64, tol: f64) -> f64 {
    let scale = r.args.last().expect("scale").0;
    let n = r.args[0].0.abs().max(r.args[1].0.abs());
    c * (n + 1.0) * eps * scale / tol
}

#[test]
fn legendre_functions_f64_match_mpmath_and_scipy() {
    for (name, tol_mp, tol_sp, _, c, _) in LEGENDRE_TOL {
        let all = rows(name);
        assert!(all.len() > 60, "{name}: {} rows", all.len());
        for r in all.iter().filter(|r| r.is_f64()) {
            let a: Vec<f64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, legendre_floor(r, c, f64::EPSILON, tol_mp));
            assert!(
                e <= tol_mp,
                "{name}{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
                r.line,
                r.reference
            );
            if let Some(s) = r.scipy.filter(|s| s.is_finite()) {
                let e = error(got, (s, 0.0), legendre_floor(r, c, f64::EPSILON, tol_sp));
                assert!(
                    e <= tol_sp,
                    "{name}{a:?} (line {}): got {got:e}, scipy {s:e}, err {e:e}",
                    r.line
                );
            }
        }
    }
}

#[cfg(feature = "xprec")]
#[test]
fn legendre_functions_df64_match_mpmath() {
    for (name, _, _, tol, _, c) in LEGENDRE_TOL {
        for r in rows(name) {
            let a: Vec<Df64> = r.args_as();
            let got = eval(name, &a);
            let e = error(
                got,
                r.reference,
                legendre_floor(&r, c, 2.0_f64.powi(-105), tol),
            );
            assert!(
                e <= tol,
                "{name}{:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
                r.args,
                r.line,
                r.reference
            );
        }
    }
}

/// `pmv` of a non-integer degree: `f64` is xsf's series (accuracy 1e-14 in the
/// series, worse near the zeros); `Df64` evaluates the f64 kernel.
#[test]
fn pmv_real_degree_f64_matches_mpmath() {
    let all = rows("pmv");
    assert!(all.len() > 60, "{} rows", all.len());
    for r in all.iter().filter(|r| r.is_f64()) {
        let a: Vec<f64> = r.args_as();
        let got = eval("pmv", &a);
        // absolute 1e-13 near the zeros of the function
        let e = error(got, r.reference, 1e-13 / 1e-9);
        assert!(
            e <= 1e-9,
            "pmv{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
            r.line,
            r.reference
        );
    }
}

#[cfg(feature = "xprec")]
#[test]
fn pmv_real_degree_df64_is_as_accurate_as_the_f64_kernel() {
    for r in rows("pmv").iter().filter(|r| r.is_f64()) {
        let a: Vec<Df64> = r.args_as();
        let got = eval("pmv", &a);
        let e = error(got, r.reference, 1e-13 / 1e-9);
        assert!(
            e <= 1e-9,
            "pmv{:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
            r.args,
            r.line,
            r.reference
        );
    }
}

/// Tolerances of the second-kind rows `(name, f64 vs mpmath, Df64 vs mpmath)`.
///
/// The absolute floor is `c (n + m + 1) eps max(1, |ref|) / (1 - x^2)^(m + 1)`
/// next to a zero, where `Q_n^m` and its derivative are summed from terms of
/// that size.
const Q_TOL: [(&str, f64, f64); 4] = [
    ("lqn", 1e-9, 1e-28),
    ("lqn_d", 1e-9, 1e-28),
    ("lqmn", 1e-9, 1e-28),
    ("lqmn_d", 1e-9, 1e-28),
];

fn q_floor(name: &str, r: &Row, eps: f64, tol: f64) -> f64 {
    let (m, n, x) = if name.starts_with("lqmn") {
        (r.args[0].0, r.args[1].0, r.args[2].0)
    } else {
        (0.0, r.args[0].0, r.args[1].0)
    };
    let geom = (1.0 / (1.0 - x * x).abs()).max(1.0).powf(m + 1.0);
    let mag = r.reference.0.abs().max(1.0);
    100.0 * (n + m + 1.0) * eps * mag * geom / tol
}

#[test]
fn second_kind_f64_matches_mpmath() {
    for (name, tol, _) in Q_TOL {
        let all = rows(name);
        assert!(all.len() > 100, "{name}: {} rows", all.len());
        for r in all.iter().filter(|r| r.is_f64()) {
            let a: Vec<f64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, q_floor(name, r, f64::EPSILON, tol));
            assert!(
                e <= tol,
                "{name}{a:?} (line {}): got {got:e}, mpmath {:?}, err {e:e}",
                r.line,
                r.reference
            );
        }
    }
}

#[cfg(feature = "xprec")]
#[test]
fn second_kind_df64_matches_mpmath() {
    for (name, _, tol) in Q_TOL {
        for r in rows(name) {
            let a: Vec<Df64> = r.args_as();
            let got = eval(name, &a);
            let e = error(got, r.reference, q_floor(name, &r, 2.0_f64.powi(-105), tol));
            assert!(
                e <= tol,
                "{name}{:?} (line {}): got {got:?}, mpmath {:?}, err {e:e}",
                r.args,
                r.line,
                r.reference
            );
        }
    }
}

/// SciPy's non-finite and zero results (and the exact `+-1`), for both types.
#[test]
fn special_values_match_scipy() {
    let all = orthogonal_special_values();
    assert!(all.len() > 150, "{} special values", all.len());
    for (name, args, expected, _scipy) in all {
        let got = eval::<f64>(&name, &args);
        assert!(
            same(got, expected),
            "f64 {name}{args:?} = {got}, expected {expected}"
        );
        #[cfg(feature = "xprec")]
        {
            let a: Vec<Df64> = args.iter().map(|&x| Df64::from(x)).collect();
            let got = eval::<Df64>(&name, &a);
            assert!(
                same(got, expected),
                "Df64 {name}{args:?} = {got:?}, expected {expected}"
            );
        }
    }
}

/// The names that the tests above exercise are all the rows of the family.
#[test]
fn every_row_file_is_tested() {
    let tested: Vec<&str> = INT_NAMES
        .iter()
        .chain(REAL_NAMES.iter())
        .chain(LEGENDRE_NAMES.iter())
        .copied()
        .collect();
    assert_eq!(tested.len(), 15 + 13 + 6);
    for t in INT_TOL.iter().map(|t| t.0) {
        assert!(INT_NAMES.contains(&t));
    }
    for t in REAL_TOL.iter().map(|t| t.0) {
        assert!(REAL_NAMES.contains(&t));
    }
    for t in LEGENDRE_TOL.iter().map(|t| t.0) {
        assert!(LEGENDRE_NAMES.contains(&t));
    }
}
